<?php
require_once __DIR__ . '/../config/security.php';
start_secure_session();
require_once __DIR__ . '/../config/database.php';
require_portal_role($conn, 'superadmin', false);

start_secure_session();require_once '../config/database.php';if(($_SESSION['role']??'')!=='superadmin'){header('Location: ../auth/login.php');exit;}require_once __DIR__.'/../includes/appointment_helpers.php';$msg='';$msgType='success';if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='cancel'){if(!csrf_valid($_POST['csrf_token']??null)){$msg='Your session expired. Refresh and try again.';$msgType='error';}else{[$ok,$text]=sd_cancel_appointment($conn,(int)($_POST['appointment_id']??0),(int)$_SESSION['user_id'],'superadmin',(string)($_POST['cancel_reason']??''));$msg=$ok?$text.' The patient was notified.':$text;$msgType=$ok?'success':'error';}}$month=$_GET['month']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');$start=$month.'-01';$end=date('Y-m-t',strtotime($start));$st=$conn->prepare("SELECT a.*,CONCAT(p.first_name,' ',p.last_name) patient_name,CONCAT(d.first_name,' ',d.last_name) dentist_name FROM appointments a JOIN users p ON p.id=a.patient_id LEFT JOIN users d ON d.id=a.dentist_id WHERE a.appointment_date BETWEEN ? AND ? ORDER BY a.appointment_date,a.appointment_time");$st->bind_param('ss',$start,$end);$st->execute();$rows=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();require '../includes/ui.php';ui_header('Clinic Calendar','superadmin');ui_sidebar('superadmin','');?><div class="page-head"><div><div class="eyebrow">CLINIC CALENDAR</div><h1>Appointment Calendar</h1><div class="muted">System-wide view of patient schedules and dentist assignments.</div></div></div><?php if($msg)flash($msgType,$msg);?><section class="card"><form class="directory-search" method="get"><input type="month" name="month" value="<?=e($month)?>"><button class="btn btn-primary">Open Month</button></form><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Time</th><th>Patient</th><th>Dentist</th><th>Service</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('M d, Y',strtotime($r['appointment_date'])))?></td><td><?=e(date('h:i A',strtotime($r['appointment_time'])))?></td><td><?=e($r['patient_name'])?></td><td><?=e($r['dentist_name']?:'Unassigned')?></td><td><?=e($r['appointment_type'])?></td><td><span class="status-pill <?=e($r['status'])?>"><?=e($r['status']==='rejected'?'Declined':ucfirst($r['status']))?></span></td><td><?php if(in_array($r['status'],['pending','approved'],true)):?><form method="post" class="row-actions" onsubmit="return confirm('Cancel this appointment? The patient will be notified.')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="appointment_id" value="<?=(int)$r['id']?>"><button class="btn btn-danger btn-sm">Cancel</button></form><?php else:?><span class="muted">—</span><?php endif;?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="empty">No appointments in this month.</td></tr><?php endif;?></tbody></table></div></section><?php ui_footer();?>
